const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=s=>String(s??'').trim().replace(/\s+/g,' ').toLowerCase(),now=()=>new Date().toISOString(),today=()=>now().slice(0,10),cls='w-full min-w-0 bg-slate-950 border border-slate-700 rounded-lg px-3 py-2.5 text-sm';
const TYPES=['Inspection / Maintenance','Machine Shop'];let inventory=[],settings=[],businesses=[],cycles=[],me=null,busy=false;
const roles=x=>Array.isArray(x?.businessRoles)?x.businessRoles:[],name=x=>x?.companyName||x?.supplierName||x?.clientName||x?.name||x?.value||'';
function bal(i){return(Array.isArray(i?.stockBalances)?i.stockBalances:[]).filter(x=>+x.qty>0).map(x=>({...x,qty:+x.qty,locationType:x.locationType||'warehouse',locationId:x.locationId||'',locationName:x.locationName||'Unknown',status:x.status||'Not Available'}));}
function sum(b){const p=b.filter(x=>x.qty>0),q=['In Transit','Maintenance','Inspection','At Client','Reserved','Not Available','At Supplier','Available'];return!p.length?{status:'Not Available',location:'No Stock'}:{status:q.find(s=>p.some(x=>x.status===s))||'Not Available',location:p.length===1?p[0].locationName:`${p.length} Locations`};}
const wh=()=>settings.filter(x=>x.type==='warehouse'&&x.status!=='inactive').map(x=>({id:x.id,name:x.value,type:'warehouse'})).filter(x=>x.name),sup=()=>businesses.filter(x=>roles(x).includes('supplier')).map(x=>({id:x.id,name:name(x),type:'supplier',raw:x})).filter(x=>x.name),cli=()=>businesses.filter(x=>roles(x).includes('client')).map(x=>({id:x.id,name:name(x),type:'client',raw:x})).filter(x=>x.name);
function providers(type='Inspection / Maintenance'){const role=norm(type)==='machine shop'?'machine_shop':'service_provider';return businesses.filter(x=>roles(x).includes(role)).map(x=>({id:x.id,name:name(x),raw:x})).filter(x=>x.name).sort((a,b)=>a.name.localeCompare(b.name));}
