function addrs(x){if(!x)return[];const a=[];if(Array.isArray(x.addresses))x.addresses.forEach(v=>a.push(typeof v==='string'?v:(v?.address||v?.fullAddress||'')));['address','businessAddress','shippingAddress','officeAddress'].forEach(k=>x[k]&&a.push(typeof x[k]==='string'?x[k]:(x[k]?.address||'')));return[...new Set(a.filter(Boolean))];}
const srcList=t=>t==='client'?cli():t==='supplier'?sup():wh(),dstList=t=>t==='client'?cli():t==='supplier'?sup():t==='other'?[{id:'__other__',name:'Other Location',type:'other'}]:wh(),same=(b,l)=>b&&l&&((b.locationId&&String(b.locationId)===String(l.id))||norm(b.locationName)===norm(l.name));
