const gid=c=>c?.serviceGroupId||'',sref=c=>c?.serviceReference||c?.serviceNo||'',last=c=>[...(c?.stages||[])].reverse()[0]||null,res=c=>c?.result||(c?.lastStageResult==='Completed'?'Pass':c?.lastStageResult)||((last(c)?.result==='Completed')?'Pass':last(c)?.result)||'',isFail=c=>res(c)==='Failed';
function groups(status,byReference=false){const m=new Map();cycles.filter(c=>(status==='all'||(Array.isArray(status)?status.includes(c.status):c.status===status))&&gid(c)).forEach(c=>{const provider=String(c.providerId||last(c)?.providerId||norm(c.providerName||last(c)?.providerName||''));const reference=norm(sref(c));const g=byReference?encodeURIComponent(JSON.stringify([reference||gid(c),provider])):c.status==='return_transit'?encodeURIComponent(JSON.stringify([gid(c),c.returnBatchId||'',c.returnType||'',c.returnId||'',c.returnDate||''])):c.status==='outbound_transit'?encodeURIComponent(JSON.stringify([gid(c),provider,reference,c.serviceDate||'',c.dispatchedAt||''])):gid(c);if(!m.has(g))m.set(g,[]);m.get(g).push(c)});return[...m].map(([id,items])=>({id,items:items.sort((a,b)=>String(a.itemAlias||a.itemCode||'').localeCompare(String(b.itemAlias||b.itemCode||''),undefined,{numeric:true,sensitivity:'base'})),first:items[0],serviceReference:sref(items[0])})).sort((a,b)=>String(a.serviceReference).localeCompare(String(b.serviceReference),undefined,{numeric:true,sensitivity:'base'})||String(a.first.providerName||'').localeCompare(String(b.first.providerName||''),undefined,{numeric:true,sensitivity:'base'}));}
