const itemType=i=>settings.find(x=>x.type==='item_type'&&(x.id===i?.itemTypeId||norm(x.value)===norm(i?.type))),single=i=>itemType(i)?.quantityMode==='single',activeItem=id=>cycles.find(c=>c.itemId===id),svcBal=(b,id)=>b.find(x=>x.serviceCycleId===id||(x.locationType==='service'&&String(x.locationId)===String(id)));
function finalStatus(t,f){if(f)return'Not Available';return t==='warehouse'?'Available':t==='client'?'At Client':t==='supplier'?'At Supplier':'Not Available';}
function cacheItem(i){inventory=inventory.filter(x=>x.id!==i.id);inventory.push(i);}
async function load(){const u=auth.currentUser;if(!u)throw Error('Sign in required.');const p=await getDoc(doc(db,'users',u.uid));if(!p.exists()||p.data().status!=='active')throw Error('Active user required.');me={...p.data(),email:p.data().email||u.email||''};const[a,b,c,d]=await Promise.all([getDocs(collection(db,'settings')),getDocs(query(collection(db,'service_cycles'),where('status','in',['outbound_transit','active','ready_return','return_transit','failed']))),getDocs(collection(db,'supplier_profiles')),getDocs(collection(db,'client_profiles'))]);settings=a.docs.map(x=>({id:x.id,...x.data()}));cycles=b.docs.map(x=>({id:x.id,...x.data()}));businesses=[...c.docs.map(x=>({id:x.id,...x.data()})),...d.docs.map(x=>({id:x.id,...x.data()}))].filter(x=>x.status!=='inactive');inventory=[];}
