const field=(l,b)=>`<label class="block text-xs text-slate-400">${l}${b}</label>`,opts=(a,l)=>`<option value="">-- ${esc(l)} --</option>${[...a].sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),undefined,{numeric:true,sensitivity:'base'})).map(x=>`<option value="${esc(x.id)}" data-name="${esc(x.name)}">${esc(x.name)}</option>`).join('')}`;
function categoryOptions(){const values=[...new Set(settings.filter(x=>x.type==='category'&&x.status!=='inactive').map(x=>String(x.value||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));return`<option value="">All Categories</option>${values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}`;}
function logisticsHtml(p){return`<section id="${p}Logistics" class="border border-slate-800 rounded-xl p-3"><div class="font-semibold text-sm mb-3">Logistics</div><div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-2">${field('Provider',`<select id="${p}LP" class="${cls} mt-1">${opts(logistics(),'Optional / Internal')}</select>`)}${field('Contact Person',`<input id="${p}CP" class="${cls} mt-1">`)}${field('Contact Number',`<input id="${p}CN" class="${cls} mt-1">`)}${field('Transport / Vessel No.',`<input id="${p}TN" class="${cls} mt-1">`)}${field('Logistics Reference',`<input id="${p}LR" class="${cls} mt-1">`)}${field('Date / ETA',`<input id="${p}DT" type="date" value="${today()}" class="${cls} mt-1">`)}${field('Delivery Ticket / DO',`<input id="${p}DO" class="${cls} mt-1">`)}${field('Remark',`<input id="${p}RM" class="${cls} mt-1">`)}</div></section>`;}
