function startHtml(){return`<div class="space-y-4"><section class="border border-cyan-900/50 rounded-xl p-3"><div class="font-semibold text-cyan-300 mb-1">Start Service</div><div class="text-[11px] text-slate-400 mb-3">Enter a new Service No. / PO or use Add Items on an existing service below. Additional items keep their actual service date.</div><div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-2">${field('Service Type',`<select id="scType" class="${cls} mt-1">${TYPES.map(x=>`<option>${x}</option>`).join('')}</select>`)}${field('Source Type',`<select id="scSrcType" class="${cls} mt-1"><option value="warehouse">Warehouse</option><option value="client">Client</option><option value="supplier">Supplier</option></select>`)}${field('Source',`<select id="scSrc" class="${cls} mt-1"></select>`)}${field('Service Mode',`<select id="scMode" class="${cls} mt-1"><option>Sent To</option><option>On Site</option></select>`)}${field('Service Provider',`<select id="scProv" class="${cls} mt-1">${opts(providers(),'Service Provider')}</select>`)}${field('Service No. / PO *',`<input id="scNo" required list="scExistingRefs" class="${cls} mt-1" placeholder="New or existing reference"><datalist id="scExistingRefs"></datalist>`)}${field('Service Date',`<input id="scDate" type="date" value="${today()}" class="${cls} mt-1">`)}${field('Provider Address',`<input id="scAddr" class="${cls} mt-1">`)}</div></section><section class="border border-slate-800 rounded-xl p-3 space-y-3"><div><div class="font-semibold text-sm">Items from Source</div><div class="text-[11px] text-slate-500">Find & Add one serial number, or use Bulk Select below to find all eligible matching items.</div></div><div class="grid lg:grid-cols-[170px_minmax(0,1fr)_auto] gap-2 items-end">${field('Find By',`<select id="scLookupField" class="${cls} mt-1"><option value="alias">Wellora SN / R2R SN</option><option value="name">Description (bulk search)</option></select>`)}${field('Exact Value',`<input id="scLookupValue" class="${cls} mt-1" placeholder="Enter exact value">`)}<button type="button" id="scFind" class="bg-cyan-700 px-4 py-2.5 rounded-lg text-xs font-bold">Find & Add</button></div><div class="border border-cyan-900/40 rounded-xl p-3 space-y-3"><div><div class="font-semibold text-sm text-cyan-300">Bulk Select</div><div class="text-[11px] text-slate-500">Find every eligible matching item at the selected source. Search by registered description, keywords or serial prefix; then select individual items or all matches.</div></div><div class="grid sm:grid-cols-[minmax(0,1fr)_220px_auto] gap-2 items-end">${field('SN Prefix / Description',`<input id="scLooseValue" class="${cls} mt-1" list="scDescriptions" placeholder="Description, keywords or SN prefix"><datalist id="scDescriptions"></datalist>`)}${field('Category',`<select id="scLooseCategory" class="${cls} mt-1">${categoryOptions()}</select>`)}<button type="button" id="scLooseSearch" class="bg-cyan-800 hover:bg-cyan-700 px-4 py-2.5 rounded-lg text-xs font-bold">Search</button></div><div class="grid sm:grid-cols-2 gap-2"><label class="text-xs text-slate-400">Search Mode<select id="scSearchMode" class="${cls} mt-1"><option value="keywords">Keywords / SN prefix</option><option value="description">Registered description (exact)</option></select></label><label class="text-xs text-slate-400">Ownership<select id="scPickOwner" class="${cls} mt-1"><option value="">All eligible ownership</option><option value="owned">Owned</option><option value="third_party">R2R / Third-Party</option></select></label></div><div id="scLooseResults" class="text-xs text-slate-500">Enter a SN prefix / partial description, or choose a category.</div></div><div class="font-semibold text-sm">Items added to this service</div><div class="text-[11px] text-slate-400">Checked search results must be added using Add selected before Start Service.</div><div id="scLines" class="space-y-2"></div></section>${logisticsHtml('ss')}<button id="scStart" class="w-full bg-emerald-700 py-3 rounded-lg font-bold">Start Service</button></div>`;}
const gLabel=g=>`${g.serviceReference} · ${g.first.providerName||last(g.first)?.providerName||'Provider unavailable'} · ${g.items.length} item(s)`;
function endHtml(){const a=groups('active',true);return`<div class="space-y-4"><section class="border border-amber-900/50 rounded-xl p-3">${field('Active Service No. / PO',`<select id="scEndG" class="${cls} mt-1"><option value="">-- Select --</option>${a.map(g=>`<option value="${g.id}">${esc(gLabel(g))}</option>`).join('')}</select>`)}</section><section class="border border-slate-800 rounded-xl p-3"><div class="font-semibold text-sm mb-3">Service Results</div><div id="scEndLines" class="space-y-2 text-sm text-slate-500">Select a Service No. / PO.</div></section><div class="grid sm:grid-cols-2 gap-2">${field('End Date',`<input id="scEndDate" type="date" value="${today()}" class="${cls} mt-1">`)}${field('Remark',`<input id="scEndRm" class="${cls} mt-1">`)}</div><button id="scEnd" class="w-full bg-emerald-700 py-3 rounded-lg font-bold">End Service</button></div>`;}
function restartHtml(){const a=groups('failed',true);return`<div class="space-y-4"><section class="border border-red-900/50 rounded-xl p-3"><div class="font-semibold text-red-300 mb-2">Restart</div><div class="text-[11px] text-slate-500 mb-3">Restart can continue at the current provider or route selected failed item(s) to a new service provider. Use Return when the item should go back to a warehouse, client or supplier.</div>${field('Failed Service No. / PO',`<select id="scRestartG" class="${cls} mt-1"><option value="">-- Select --</option>${a.map(g=>`<option value="${g.id}">${esc(gLabel(g))}</option>`).join('')}</select>`)}</section><section class="border border-slate-800 rounded-xl p-3"><div class="font-semibold text-sm mb-3">Failed Items</div><div id="scRestartLines" class="space-y-2 text-sm text-slate-500">Select a failed Service No. / PO.</div></section><section class="border border-cyan-900/50 rounded-xl p-3 space-y-3"><div><div class="font-semibold text-cyan-300">Next Service Leg</div><div class="text-[11px] text-slate-500 mt-1">Choose the next service type and provider. Sent To creates transit when the provider changes; On Site keeps the item at its current physical location.</div></div><div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-2">${field('Service Type',`<select id="scRestartType" class="${cls} mt-1">${TYPES.map(x=>`<option>${x}</option>`).join('')}</select>`)}${field('Service Mode',`<select id="scRestartMode" class="${cls} mt-1"><option>Sent To</option><option>On Site</option></select>`)}${field('Service Provider',`<select id="scRestartProv" class="${cls} mt-1"></select>`)}${field('New Service No. / PO *',`<input id="scRestartNo" class="${cls} mt-1" required>`)}${field('Provider Address',`<input id="scRestartAddr" class="${cls} mt-1">`)}${field('Restart / Dispatch Date',`<input id="scRestartDate" type="date" value="${today()}" class="${cls} mt-1">`)}${field('Reason / Instruction',`<input id="scRestartRm" class="${cls} mt-1" placeholder="Reason / instruction for restart">`)}</div></section>${logisticsHtml('rr')}<button id="scRestart" class="w-full bg-red-700 py-3 rounded-lg font-bold">Restart Selected Item(s)</button></div>`;}
function returnHtml(){const a=returnGroups();return`<div class="space-y-4"><section class="border border-cyan-900/50 rounded-xl p-3 space-y-3">${field('Completed / Failed Service No. / PO',`<select id="scRetG" class="${cls} mt-1"><option value="">-- Select --</option>${a.map(g=>`<option value="${g.id}">${esc(gLabel(g))}</option>`).join('')}</select>`)}<div class="text-[11px] text-slate-500">Passed and failed off-site items may be returned. Failed items remain Not Available after arrival.</div><div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-2">${field('Destination Type',`<select id="scDstType" class="${cls} mt-1"><option value="warehouse">Warehouse</option><option value="client">Client</option><option value="supplier">Supplier</option><option value="other">Other Location</option></select>`)}${field('Destination',`<select id="scDst" class="${cls} mt-1"></select>`)}${field('Address',`<input id="scDstAddr" class="${cls} mt-1">`)}${field('Return Reference',`<input id="scRetRef" class="${cls} mt-1">`)}</div></section><div id="scRetLines" class="space-y-2"></div>${logisticsHtml('sr')}<button id="scReturn" class="w-full bg-emerald-700 py-3 rounded-lg font-bold">Start Return Transit</button></div>`;}
function providerTransitHtml(){const a=groups('outbound_transit');return!a.length?'':`<section class="space-y-3"><div class="font-bold">Transit to Service Provider</div>${a.map(g=>`<div class="border border-amber-900/60 rounded-xl p-3"><div class="flex justify-between gap-3"><div><div class="font-semibold text-amber-300">${esc(g.serviceReference)}</div><div class="text-xs text-slate-400">${esc(g.first.serviceDate||'')} · ${esc(g.first.sourceName||'')} → ${esc(g.first.providerName||'Service Provider')} · ${g.items.length} item(s)</div></div><span class="text-xs text-amber-200">In Transit to Provider</span></div><div class="grid sm:grid-cols-2 gap-2 mt-3">${field('Arrival Date',`<input id="pa-${g.id}" type="date" value="${today()}" class="${cls} mt-1">`)}${field('Remark',`<input id="pr-${g.id}" class="${cls} mt-1">`)}</div><button class="providerArrive w-full bg-amber-700 py-2.5 rounded-lg mt-3" data-g="${g.id}">Arrive at Provider</button></div>`).join('')}</section>`;}
function transitHtml(){const a=groups('return_transit');return!a.length?'':`<section class="space-y-3"><div class="font-bold">Return In Transit</div>${a.map(g=>`<div class="border border-cyan-900/60 rounded-xl p-3"><div class="flex justify-between"><div><div class="font-semibold text-cyan-300">${esc(g.serviceReference)}</div><div class="text-xs text-slate-400">${esc(g.first.returnDate||g.first.serviceDate||'')} · ${esc(g.first.returnName||'')} · ${g.items.length} item(s)</div></div><span class="text-xs">In Transit</span></div><div class="grid sm:grid-cols-2 gap-2 mt-3">${field('Arrival Date',`<input id="ad-${g.id}" type="date" value="${today()}" class="${cls} mt-1">`)}${field('Remark',`<input id="ar-${g.id}" class="${cls} mt-1">`)}</div><button class="arrive w-full bg-emerald-700 py-2.5 rounded-lg mt-3" data-g="${g.id}">Arrive</button></div>`).join('')}</section>`;}
function openHtml(){const a=groups('all',true);if(!a.length)return'';return `<section class="space-y-2"><div class="font-bold">Open Service Cycles</div>${a.map(g=>{const labels={active:'Under Service',failed:'Failed',ready_return:'Ready to Return',outbound_transit:'Transit to Provider',return_transit:'Return In Transit'},counts=Object.entries(labels).map(([k,l])=>[l,g.items.filter(c=>c.status===k).length]).filter(x=>x[1]);return `<div class="border border-slate-800 rounded-xl p-3"><div class="flex flex-wrap justify-between gap-2"><div><div class="font-semibold text-cyan-300">${esc(g.serviceReference)}</div><div class="text-xs text-slate-400">${esc(g.first.providerName||last(g.first)?.providerName||'Provider unavailable')} · ${g.items.length} open item(s)</div></div><div class="text-xs">${counts.map(([l,n])=>esc(l)+' '+n).join(' · ')}</div></div><div class="flex flex-wrap gap-2 mt-3">${can('servicecycle.add')?`<button type="button" class="scAddExisting bg-cyan-700 px-3 py-2 rounded-lg text-xs" data-g="${esc(g.id)}">Add Items</button>`:''}</div><details class="mt-2"><summary class="cursor-pointer text-xs text-cyan-300">View Items</summary><div class="space-y-2 mt-2 max-h-96 overflow-auto">${g.items.map(c=>`<div class="border-t border-slate-800 pt-2 text-xs"><b>${esc(c.itemAlias||c.itemCode||c.itemId)}</b> · ${esc(labels[c.status]||c.status)}<div class="text-slate-400">${esc(c.itemName||'')} · ${esc(c.serviceDate||'')} · ${esc(c.sourceName||'')} · ${esc(c.serviceMode||'')}</div></div>`).join('')}</div></details></div>`}).join('')}</section>`;}
function shell(a='start'){return`<div id="serviceCycleWorkflow" data-ims-service-cycle-module="13" class="space-y-5">${actionHtml()}<div id="scMount">${a==='end'?endHtml():a==='restart'?restartHtml():a==='return'?returnHtml():startHtml()}</div>${providerTransitHtml()}${transitHtml()}${openHtml()}</div>`;}
function source(){const e=$('scSrc'),o=e?.selectedOptions?.[0];return e?.value?{id:e.value,name:o?.dataset?.name||o?.textContent||'',type:$('scSrcType')?.value||'warehouse'}:null;}
